svg:


/*  Crossmatch Guardian User Guidance Color Scheme
	#D1D2D4 - Light blue gray background
	#525E66 - Dark gray of prism boarder
	#0479BF - Prism light blue fill
	#0F5E8F - Prism dark blue outline
	#ECECED - Initial animated hand outline
	#FFFFFF opacity="0.5"  - Initial animated hand fill

	#FFBF40 - Yellow pressure corona
	#5CE224	- Prism capture complete green

*/




	//begin loading page.
	function onLoad() {
		window.parent.parseUrlArguments();
		Update();

		// force refresh.
		window.parent.svgUpdate = function() { Update();}
	}

	/* Update will get image of thumbs
	*/
	function Update() {
		try {
			// Set blue prism at start
			window.parent.changePrismaColor("#0479BF");

			window.parent.setFirstLooping(true);	//	prevent web page from reloading until after done with update

			var badshapeGraphic = document.getElementById('BadshapeBackground');
			badshapeGraphic.setAttribute("display","none");	// hide elements

			// Get URI argument from html
			var args = window.parent.getArguments();


			//change the default graphic, if the args is correct
			if (args == null)
				return;			// Return - nothing to do

			// Diplay Result icon. Limit to the icon # 0 to 8 and 11 in graphic array.
			if (args.Result >= 0 && args.Result <= 11) {	
				SetResult(args.Result);
			}

			// Enable buttons
			SetButton(args.ButtonRetry, "Retry");
			SetButton(args.ButtonConfirm, "Confirm");


			// Push finger values of all invalid or missing fingers into hiddenFinger array
			// Entries added to the hiddenFinger array must have the value that matches the image class name
			// Add entries to the hiddenFinger array in any order
			// setMissingFinger and setHiddenFinger will remove hiddenFinger iamge elements.
			if(args.FP6==0 || args.FP1==0) {
				var hiddenFinger = [];
				if(args.FP6==0)
					hiddenFinger.push(6);		// add new entry to array to hide left thumb
				if(args.FP1==0)
					hiddenFinger.push(1);		// add new entry to array to hide right thumb


				setMissingFinger(hiddenFinger);		// Display "ghost" image in place of missing finger

				// TODO: Add support for Hidden finger
				//setHiddenFinger(hiddenFinger);	// Completely remove image of missing finger
													// For now, 
			}


			/**********************************************************************
			  The priority of the various states is determined here:
				1st - if acquired - animate acquire compelete in loop forever via SetAcquireComplete()
				2nd - qualified - hightlight ideal corona and return via SetQualified()
				3rd - peripherality - animate reposition hand in loop forever via SetPeripherality()
				4th - badshape - animate bad shap hand in loop forever via SetBadshape()
				5th - pressure	- hightlight pressure corona and return via SetPressure()
				6th - confusion - animate confusion/wrong hand in loop forever via SetConfusion()
				7th - tracking  - animate tracking hand in loop forever via SetTracking()
				8th - rotation - animate tracking hand in loop forever via SetRotation()
			**************************************************************************/

			// Check if capture is done.
			if(args.acquired) {
				SetAcquireComplete();	 // If acquired argument set to true display capture complete animation 
				return;
			}

			// All OK (qualified)
			if(args.qualified) {
				SetQualified();
				return;
			}

			// Analyse Peripherality
			if(args.peripherality && args.peripherality.length > 0) {
				SetPeripherality(args.peripherality);
				return;
			}

			// Animate Badshape
			if(args.badshape) {
				SetBadshape();
				return;
			}

			// Analyse the Pressure
			if(args.pressure && args.pressure.length > 0) {
				SetPressure(args.pressure);
				return;
			}

			// Animate Confusion
			if(args.confusion) {
				SetConfusion();
				return;
			}

			// Animate Tracking
			if(args.tracking) {
				SetTracking();
				return;
			}

			// Animate Rotation
			if(args.rotation && args.rotation != 0 ) {
				SetRotation(args.rotation);
				return;
			}

			window.parent.setFirstLooping(false);	// false will force web page to reload via svgobj.location.reload(true) call

		}
		catch(ex) {
			alert(ex);
			//document.write("Update Error"+ex);
		}
	}


	/********************************************************************************
		Called by Update
		SetResult will show or hide the Result Icons by Result-Parameter
	Input:
	  result icon number
		1 - green Icon (OK) displayed when capture is complete
		2 - General error
		3 - Clean Platen
		4 - Recording error
		5 - Roll error
		6 - Segmentation error displayed if flat captured images can not be segmented
		7 - Quality-Check error
		8 - Sequence-Check error displayed when fingerprint does not match flat capture
	********************************************************************************/
	function SetResult(result) {
	  	var i;

		// loop to hide all of the Result Icons and show only the correct one
		for (i = 1; i <= 11; i++) {
			// All the Result icon images are in the format IDIconResult_X where X is the Argument number 
			var resultIcon = document.getElementById('IDIconResult_' + i);
			if (resultIcon) {
				if (i == result)
					resultIcon.setAttribute("display","inline");	// Display icon
				else
					resultIcon.setAttribute("display","none");		// hide icon
			}
		}
	}

	/********************************************************************************
	  called by Update
	  SetButton will change the button icon to the active or inactive state
	  The button names are:
		IDButtonRetryActive
		IDButtonRetryInactive
		IDButtonConfirmActive
		IDButtonConfirmInactive
	INPUTS:
		state 	0 - inactive button is grayed out
				1 - active button is raised
				2 - button is hidden
		button  - string containing the name of the button. Used to get graphics element
				 must be set to "Retry" or "Confirm".
	********************************************************************************/
	function SetButton(state, button) {
  		var ActiveButtonIcon = document.getElementById('IDButton' + button + 'Active');
  		var InactiveButtonIcon = document.getElementById('IDButton' + button + 'Inactive');

		switch(state) {
			case 0:
				//inactive
				ActiveButtonIcon.setAttribute("display","none");
				InactiveButtonIcon.setAttribute("display","inline");
				if (button == "Confirm") {
					MoveRetryButton(0);
				}
				break;

			case 1:
				//active
				ActiveButtonIcon.setAttribute("display","inline");
				InactiveButtonIcon.setAttribute("display","none");
				if (button == "Confirm") {
					MoveRetryButton(0);
				}
				break;

			case 2:
				//hidden
				ActiveButtonIcon.setAttribute("display","none");
				InactiveButtonIcon.setAttribute("display","none");
				//if the Button "Confirm" is not visible, move the Retry-Button to right
				if (button == "Confirm") {
					MoveRetryButton(1);
				}
				break;

			default:
				//inactive
				ActiveButtonIcon.setAttribute("display","none");
				InactiveButtonIcon.setAttribute("display","inline");
				break;
		}
	}


	/********************************************************************************
	  called by SetButton
	  MoveRetryButton will preposition Retry button if Confirm button is hidden

	INPUTL
		position - Retry button position
		           0 - initial possition as defined by SVG graphics
				   1 - move button to left
	********************************************************************************/
	function MoveRetryButton(position) {
		var retryBtn1 = document.getElementById('IDButtonRetryActive');
		var retryBtn2 = document.getElementById('IDButtonRetryInactive');

		if (position == 1) {
			retryBtn1.setAttribute("transform","translate(113,0)");
			retryBtn2.setAttribute("transform","translate(113,0)");
		} 
		else {
			retryBtn1.setAttribute("transform","translate(0,0)");	// original position
			retryBtn2.setAttribute("transform","translate(0,0)");			
		}
	}

	/********************************************************************************
	  setMissingFinger will check for hidden/missing fingers. 
	   Will display "ghost" image segment with class name matching the missing finger.
	   missingFinger[] contains finger number. i.e 1-right thumb, 6-left thumb
	   The class = LiveFingerX where X is 1 or 6 contains finger image element.
	********************************************************************************/
	function setMissingFinger(missingFinger) {

		// loop through missingFinger array 
		// remove elements that match the fingerNumerationArr array
		// all finger elements have ClassNames in the format LiveFingerX

		for (var i = 0; i < missingFinger.length; i++) {

			// Loop through all the "LiveFinger" Class elements and hide the elements.
			var className = "LiveFinger"+missingFinger[i];
			var missingTargetArr = document.getElementsByClassName(className);
			for (j = 0; j < missingTargetArr.length; j++) {
				missingTargetArr[j].setAttribute("display","none");	// Hide finger "present" element
			}

		}
	}


	/********************************************************************************
	  Called by Update()
	  Called when acquired argument set to true 
	  This function will display the capture complete animation.
	  Flow:
	   1. hide capturing image elements
	   2. diplay the captured corona image elements
	   3. Flash the platen color to green
	   4. hide live corona pressure outline image elements
	   5. Call RemoveHand function to display the capture complete animation
	   6. Animate with a loop forever in RemoveHand
	********************************************************************************/
	function SetAcquireComplete() {
	  	var i;

		// hide all of the all the live finger pressure coronas
	  	var fingersCoronasArr = document.getElementsByClassName('FingerCorona');
		for (i = 0; i < fingersCoronasArr.length; i++) {
			fingersCoronasArr[i].setAttribute("display","none");
		}

		// Display the "Ideal Corona Acquired"
		var acquiredTargetArr = document.getElementsByClassName('AcquiredCorona');
		for (i = 0; i < acquiredTargetArr.length; i++) {
			acquiredTargetArr[i].setAttribute("display","inline");
		}

		// set prisma green for short time and hide all elements
		window.parent.changePrismaColor("#5CE224");			// make platen Green

		setTimeout( function() {
			window.parent.changePrismaColor("#0479BF");		// back to light blue

			var corona = document.getElementById('IdealLiveCorona');
			corona.setAttribute("display","none");

			for (i = 0; i < acquiredTargetArr.length; i++) {
				acquiredTargetArr[i].setAttribute("display","none"); // Hide elements
			}
			setTimeout( function() {
				//HideHand(0.9);	// fade out
				RemoveHand();		// Animated removal of hand
			}
			,600);	
		}
		,1000);	
	}

	/********************************************************************************
	 HideHand is not used.
	 Called when acquired argument set to true 
	 This function will display the capture complete hand fade out.
	 Flow:
	  1. hide thumb image elements
	  2. fade out capturing image elements once.
	********************************************************************************/
	function HideHand(opacity) {
  		var hand = document.getElementById('TwoThumbs');
		hand.setAttribute("opacity",opacity);
		opacity = opacity - 0.05;
		if (opacity > 0.05) {		
  			window.setTimeout( 
				function(){ 
					HideHand(opacity); 	// recursive call
				}
				, 40 );
		} 
		else {
			hand.setAttribute("opacity",0);	// Done. Finger completely  faded out
		}
	}

	/********************************************************************************	
	 Called from SetAcquireComplete
	 RemoveHand will display one remove hand animation sequence, then sleep for 300 msec
	********************************************************************************/
	function RemoveHand() {
		var regularHandRight = document.getElementById('Thumb_right');
		var regularHandLeft = document.getElementById('Thumb_left');

		regularHandRight.setAttribute("transform","translate(0,0)");
		regularHandLeft.setAttribute("transform","translate(0,0)");

		window.setTimeout( 
			function(){ 
				RemoveHand2(); 
			}
			,300);  // 300 millisecond delay before starting next animation sequence
	}

	/********************************************************************************
	// RemoveHand2 will display remove hand animation
	********************************************************************************/
	function RemoveHand2() {
		var regularHandRight = document.getElementById('Thumb_right');
		var regularHandLeft = document.getElementById('Thumb_left');
		regularHandRight.setAttribute("display","none");
		regularHandLeft.setAttribute("display","none");
		var step=0;

		var endX = -360;
		var endY = -700;
		var percentageMoved = 0;
		var scaleRate = 1;

		window.clearInterval(window.timer);
		window.timer = window.setInterval(
			function() {
				percentageMoved += 0.05;
				scaleRate = 1 + percentageMoved;
				if (percentageMoved > 1.05) {
					window.clearInterval(window.timer);
					setTimeout(
						function(){
							RemoveHand();
						}
						,1200); 	// 1200 millisecond delay after each animation cycle
					return; 
				}
				else {
				  	var x2 = -2.5 * endX * percentageMoved;
					var x = 4.5 * endX * percentageMoved;
				  	var y = endY * percentageMoved;

					// Build the text versions of the translate and scale transformation
					var trans = "translate(" + x + ", " + y + ")";
					var trans2 = "translate(" + x2 + ", " + y + ")";
					var scale = "scale(" + scaleRate + ", " + scaleRate + ")";

					// Apply the transformation 
					regularHandLeft.setAttributeNS(null, "transform", trans + " " + scale);
					regularHandLeft.setAttribute("display","inline");
					regularHandRight.setAttributeNS(null, "transform", trans2 + " " + scale);
					regularHandRight.setAttribute("display","inline");
				}				
			} 
		  ,100);  	 // 100 millisecond delay after each animation frame			
	}

	/********************************************************************************
	 called by Update
	 Called when qualified (LSCAN_OBJECT_GOOD) argument set to true 
	 This function will display the good hand placement image.
	 This function does not do any animation.
	 Flow:
	  1. hide live corona pressure outline image elements
	  2. displaying good qualified hand placement image
	  3. return
	********************************************************************************/
	function SetQualified() {
	  	var i;

		// hide all of the all the live finger pressure coronas
	  	var fingersCoronasArr = document.getElementsByClassName('FingerCorona');
		for (i = 0; i < fingersCoronasArr.length; i++) {
			fingersCoronasArr[i].setAttribute("display","none");	// hide finger pressure elements
		}

		// Get the FingerCorona qualified class elements
		// show only the qualified good hand pressure corona image
		// qualifiedTargetArr contains 2 elements 
		var qualifiedTargetArr = document.getElementsByClassName('FingerCorona qualified');
		for (i = 0; i < qualifiedTargetArr.length; i++) {
			qualifiedTargetArr[i].setAttribute("display","inline");
		}

		window.parent.setFirstLooping(false);	// false will force web page to reload via svgobj.location.reload(true) call
	}


	/********************************************************************************
	 called by Update
	 Called when confusion (LSCAN_OBJECT_CONFUSION) argument set to true 
	 This function will display the confusion animation.
	 LSE not lickly to return a LSCAN_OBJECT_CONFUSION quality when capturing thumbs
	 Application can use this animation whenever they chose.
	 Flow:
	  1. hide correct hand capturing image 
	  2. hide live corona pressure outline image elements
	  3. flash dim live corona pressure outline image elements
	  4. display the confusion image animation
	  5. Animate with a loop forever with recursive call 
	********************************************************************************/
	function SetConfusion() {

		//hide thumbs
		var regularHandRight = document.getElementById('Thumb_right');
		var regularHandLeft = document.getElementById('Thumb_left');
		regularHandRight.setAttribute("display","none");
		regularHandLeft.setAttribute("display","none");

		var corona = document.getElementById('IdealLiveCorona');			
		corona.setAttribute("display","none");

		var endX = 60;
		var endY = -600;
		var percentageMoved = 0;
		var scaleRate = 1;

		var step=0;
		setTimeout( 
			function() {
				corona.setAttribute("opacity",0.6);		// dim ideal live corona pressure outline element

				//Flash corona on and off when hand is in incorrect possition.
				window.timer = window.setInterval(	
					function() {
						if (step%2 == 0) {
							corona.setAttribute("display","inline");	// Display (on)
						} 
						else {
							corona.setAttribute("display","none");		// Hide (off)
						}
						step++;
					}
					,500);		// Toggle ideal live corona outline on and off every 500 millisecond
			}
			, 500 );	

		setTimeout(function() {
			window.clearInterval(window.timer);
			corona.setAttribute("display","inline");
			window.timer = window.setInterval(
				function() {
					percentageMoved += 0.05;
					scaleRate2 = 2 - percentageMoved;
					if (percentageMoved > 1.05) {
						window.clearInterval(window.timer);
						corona.setAttribute("opacity",1); 
						setTimeout(function(){
							SetConfusion();		// recursive call
						}
						,1200); 
						return; 
					}
					else {
						var x = -15 * endX * (1 - percentageMoved);
						var x2 = endX * (1 - percentageMoved);
						var y2 = endY * (1- percentageMoved);

						// Build the text versions of the translate and scale transformation
						var trans = "translate(" + x + ", " + y2 + ")";
						var trans2 = "translate(" + x2 + ", " + y2 + ")";
						var scale2 = "scale(" + scaleRate2 + ", " + scaleRate2 + ")";

						// Apply the transformation 
						regularHandLeft.setAttributeNS(null, "transform", trans + " " + scale2);
						regularHandLeft.setAttribute("display","inline");
						regularHandRight.setAttributeNS(null, "transform", trans2 + " " + scale2);
						regularHandRight.setAttribute("display","inline");
					}				
				} 
				,100);  
		},2500);	// 2500 millisecond delay after each animation cycle
	}


	/********************************************************************************
	 called by Update
	 Called when tracking (LSCAN_OBJECT_TRACKING_NOT_OK) argument is set to true 
	 This function will display the tracking animation.
	 Flow:
	   1. Get tracking images
	        get two copies of the both thumbs images
	        Get copy of the ideal live thumb pressure corona outline elements
	        Set image opacity to dim images
	   2. Display correct/wrong hand vibration animation
	   3. Display bright correct hand position
	   4. Display bright live corona pressure outline image element
	   5. Wait 2 seconds
	   6. Animate with a loop forever using a recursive call 
	********************************************************************************/
	function SetTracking() {
		var thumbLeftRegular = document.getElementById('Thumb_left');
		thumbLeftRegular.setAttribute("opacity",0.9);
		var thumbRightRegular = document.getElementById('Thumb_right');
		thumbRightRegular.setAttribute("opacity",0.9);

		var clonedThumbLeft = thumbLeftRegular.cloneNode(true);
		thumbLeftRegular.parentNode.appendChild(clonedThumbLeft);
		clonedThumbLeft.setAttribute("opacity",0.7);
		var clonedThumbRight = thumbRightRegular.cloneNode(true);
		thumbRightRegular.parentNode.appendChild(clonedThumbRight);
		clonedThumbRight.setAttribute("opacity",0.7);

		var coronaLeft = document.getElementById('IdealLiveCoronaLeft');			
		coronaLeft.setAttribute("opacity",0.6);
		var coronaRight = document.getElementById('IdealLiveCoronaRight');			
		coronaRight.setAttribute("opacity",0.6);

		var step=0;
		// Toggle between correct and wrong position (shake/vibrate thumbs)
		window.timer = window.setInterval(
			function() {
				if (step%2 == 0) {
					thumbLeftRegular.setAttribute("transform", "translate(" + 3 + ", " + 0 + ")");
					clonedThumbLeft.setAttribute("transform", "translate(" + -1 + ", " + 0 + ")");
					thumbRightRegular.setAttribute("transform", "translate(" + -3 + ", " + 0 + ")");
					clonedThumbRight.setAttribute("transform", "translate(" + 1 + ", " + 0 + ")");
				} else {
					thumbLeftRegular.setAttribute("transform", "translate(" + -3 + ", " + 0 + ")");
					clonedThumbLeft.setAttribute("transform", "translate(" + 1 + ", " + 0 + ")");
					thumbRightRegular.setAttribute("transform", "translate(" + 3 + ", " + 0 + ")");
					clonedThumbRight.setAttribute("transform", "translate(" + -1 + ", " + 0 + ")");
				}
			  step++;
			} 
			,100);	// 100 millisecond delay after animation frame

		// Display Thumbs in correct position
  		setTimeout(
			function() {
				window.clearInterval(window.timer);
				(clonedThumbLeft) ? clonedThumbLeft.parentNode.removeChild(clonedThumbLeft) : false;
				(clonedThumbRight) ? clonedThumbRight.parentNode.removeChild(clonedThumbRight) : false;

				thumbLeftRegular.setAttribute("transform", "translate(" + 0 + ", " + 0 + ")");
				thumbLeftRegular.setAttribute("opacity",1);
				thumbRightRegular.setAttribute("transform", "translate(" + 0 + ", " + 0 + ")");
				thumbRightRegular.setAttribute("opacity",1);

				setTimeout(
					function(){
						coronaLeft.setAttribute("opacity",1); 	// Bright ideal corona pressure outline element
						coronaRight.setAttribute("opacity",1);	// Bright ideal corona pressure outline element
					}
					,200);

				setTimeout(
					function(){
						SetTracking();		// Recursive call to do animation
					}
					, 2000);	// 2 second delay after each animation cycle
			},1000);	// display tracking shake animation for 1 second
	}

	/********************************************************************************
	 called by Update
	 Called when badshape (LSCAN_OBJECT_BAD_SHAPE) argument set to true 
	 This function will display the bad shape animation.
	 Flow:
	  1. hide thumb images elements
	  2. hide live corona pressure outline image elements
	  3. Display background and Guardian
	  4. Get both bad shape image elements (flat and curved)
	  5. Display flat hand and hide curved hand
	  6. wait 1 second
	  7. Hide flat hand and display curved hand
	  8. Set setFirstLooping flag to for web page reload and thus allow this animation
	  9. wait 1 second
	  10. return
	********************************************************************************/
	function SetBadshape() {
		var regularHand = document.getElementById('TwoThumbs');
		regularHand.setAttribute("display","none");		// Hide

		var corona = document.getElementById('IdealLiveCorona');			
		corona.setAttribute("display","none");		// Hide ideal corona pressure outline element

		var badshapeGraphic = document.getElementById('BadshapeBackground');
		badshapeGraphic.setAttribute("display","inline");

		var flatHand = document.getElementById('BadShapHandFlat');
		var curvedHand = document.getElementById('BadShapHandCurved');

		var step=0;
		window.timer = window.setInterval(	
			function() {
				if (step%2 == 0) {
					flatHand.setAttribute("display","inline");
					curvedHand.setAttribute("display","none");
				} else {
					flatHand.setAttribute("display","none");
					curvedHand.setAttribute("display","inline");
				}
			  	step++;
			  	if (step == 2)
					// SetFirstLooping to false to allow animation
					window.parent.setFirstLooping(false);	// false will force web page to reload via svgobj.location.reload(true) call
			}
			,1000);		// 1 second delay after each animation frame and each cycle
	}


	/********************************************************************************
	 called by Update
	 Called when rotation (LSCAN_OBJECT_ROTATED_CLOCKWISE or
	  LSCAN_OBJECT_ROTATED_COUNTERCLOCKWISE) argument is set 
	 This function will display the rotation animation.
	 Flow:
	   1. Get correct thumb image
	   2. Rotate thumb image to incorrect position and display 
	   3. hide live corona pressure outline image elements
	   4. flash dim live corona pressure outline image elements
	   5. Display thumb rotation animation
	   6. Display bright live corona pressure outline image elements
	   7. wait 2 second
	   8. Animate with a loop forever using a recursive call 

	 INPUT: rotation is set to + or - 45 to control rotation direction
	********************************************************************************/
	function SetRotation(rotation) {
		if (rotation > 0) {
			rotation = 45;
			centerYleft = 275;
			centerYright = 278;
		} else {
			rotation = -25;
			centerYleft = 475;
			centerYright = 478;
		}

		//Get correct thumb position 
		var thumbLeftRegular = document.getElementById('Thumb_left');
		var thumbRightRegular = document.getElementById('Thumb_right');

		//Get rotated position
		thumbLeftRegular.setAttribute("transform", "rotate(" + (rotation*0.75) + ",300, " + centerYleft + ")");
		thumbRightRegular.setAttribute("transform", "rotate(" + -(rotation*0.75) + ",503, " + centerYright + ")");

		var coronaLeft = document.getElementById('IdealLiveCoronaLeft');
		coronaLeft.setAttribute("display","none");
		var coronaRight = document.getElementById('IdealLiveCoronaRight');
		coronaRight.setAttribute("display","none");

		var step=0;
		setTimeout( 
			function() {
				coronaLeft.setAttribute("opacity",0.6);
				coronaRight.setAttribute("opacity",0.6);

				//Flash corona on and off when hand is in incorrect possition.
				window.timer = window.setInterval(
					function() {
						if (step%2 == 0) {
							coronaLeft.setAttribute("display","inline");		// Display (on)
							coronaRight.setAttribute("display","inline");
						}
						else {
							coronaLeft.setAttribute("display","none");		// Hide (off)
							coronaRight.setAttribute("display","none");
						}
						step++;
					}
					,500);		// Toggle ideal live corona outline on and off every 500 millisecond
			}
			, 500 );

		// Animate hand rotation back to correct position
		setTimeout(
			function() {
				var percentageMoved = 0;
				window.clearInterval(window.timer);

				coronaLeft.setAttribute("display","inline");
				coronaRight.setAttribute("display","inline");
				window.timer = window.setInterval(
					function() {
						percentageMoved += 0.1;
						if (percentageMoved > 1) {
							window.clearInterval(window.timer); 
							coronaLeft.setAttribute("display","inline");
							coronaRight.setAttribute("display","inline");
							setTimeout(
								function(){
									coronaLeft.setAttribute("display","inline");
									coronaLeft.setAttribute("opacity",1);
									coronaRight.setAttribute("display","inline");
									coronaRight.setAttribute("opacity",1);
								}
								, 200); 
							setTimeout(
								function(){
									SetRotation(rotation);	// recursive call
								}
								, 2000); 
							return; 
						}
						else {
							var x = (rotation*0.75) * (1 - percentageMoved);

							// Apply the transformation 
							thumbLeftRegular.setAttribute("transform", "rotate(" + x + ",300, " + centerYleft + ")");
							thumbRightRegular.setAttribute("transform", "rotate(" + -x + ",503, " + centerYright + ")");
							step++;
						}
					} ,100);  
			}
		,2000);
	}


	/********************************************************************************
	 called by SetPeripherality
	 Called when the peripherality arguments are set to true for only one thumb
	 This function will display the peripherality animation.
	 Flow:
	  1. Get correct thumb and corona
	  2. Get wrong thumb position
	  3. hide live corona pressure outline image elements
	  4. flash dim live corona pressure outline image elements
	  5. Display live corona pressure outline image elements
	  6. displaying peripherality image animation
	  7. Animate with a loop forever using a recursive call 
	INPUTS: deltaX > 0 then we animate right thumb
			deltaX < 0 then we animate left thumb
			deltax = 0 then we animate both thumbs
	********************************************************************************/
	function AnimatePeripherality(deltaX, deltaY) {

		// left thumb
		var thumbRegular = document.getElementById('Thumb_left');
		var corona = document.getElementById('IdealLiveCoronaLeft');			

		// right thumb
		if (deltaX > 0)	{ 
			thumbRegular = document.getElementById('Thumb_right');			
			corona = document.getElementById('IdealLiveCoronaRight');			
		}

		//Get wrong position
		thumbRegular.setAttribute("transform", "translate(" + deltaX + ", " + deltaY + ")");

		corona.setAttribute("display","none");

		// both thumbs LSCAN_OBJECT_POSITION_TOO_HIGH
		if (deltaX == 0 && deltaY < 0)	{
			// also need to animate 2nd thumb
			var thumbRegular2 = document.getElementById('Thumb_right');			
			thumbRegular2.setAttribute("transform", "translate(" + deltaX + ", " + deltaY + ")");

			var corona2 = document.getElementById('IdealLiveCoronaRight');			
			corona2.setAttribute("display","none");
		}

		var step=0;
		setTimeout( 
			function() {
				corona.setAttribute("opacity",0.6);
				if (corona2) 
					corona2.setAttribute("opacity",0.6);

				//Flash corona on and off when hand is in incorrect possition.
				window.timer = window.setInterval(
					function() {
						if (step%2 == 0) {
							corona.setAttribute("display","inline");	// Display (on)
							if (corona2) corona2.setAttribute("display","inline");
						}
						else {
							corona.setAttribute("display","none");		// Hide (off)
							if (corona2) corona2.setAttribute("display","none");
						}
						step++;
					}
					,500);		// Toggle ideal live corona outline on and off every 500 millisecond
			}
			, 500 );

		// After ideal live corona flashes, start hand animation
  		setTimeout(
			function() {
				var percentageMoved = 0;
				window.clearInterval(window.timer);

				corona.setAttribute("display","inline");
				if (corona2) corona2.setAttribute("display","inline");

				window.timer = window.setInterval(
					function() {
						percentageMoved += 0.1;
						if (percentageMoved > 1) {
							window.clearInterval(window.timer); 
							corona.setAttribute("display","inline");
							if (corona2) corona2.setAttribute("display","inline");
							setTimeout(
								function(){
									corona.setAttribute("opacity",1);	// Make bright 
									if(corona2) corona2.setAttribute("opacity",1);	// Make bright
								}
								, 200); 
							setTimeout(
								function(){
									AnimatePeripherality(deltaX, deltaY);
								}
								, 2000); // 2 second delay after each animation cycle 
							return; 
						}
						else {
							var x = deltaX * (1 - percentageMoved);
							var y = deltaY * (1- percentageMoved);

							var trans = "translate(" + x + ", " + y + ")";

							// Apply the transformation 
							thumbRegular.setAttribute("transform", trans);
							if (thumbRegular2) 
								thumbRegular2.setAttribute("transform", trans);
							step++;
						}
					} ,100);  
			}
			,2000);
	}

	/********************************************************************************
	 called by SetPeripherality
	 Called when the peripherality arguments are set to true for both thumbs
	 This function will display the peripherality animation.
	 Flow:
	  1. Get wrong thumbs position
	  2. hide live corona pressure outline image elements
	  3. flash dim live corona pressure outline image elements
	  4. Display bright live corona pressure outline image elements
	  5. displaying peripherality image animation
	  6. Animate with a loop forever using a recursive call 
	********************************************************************************/
	function AnimatePeripheralitySpread() {

		// Get thumbs in wrong position 
		var thumbRegularLeft = document.getElementById('Thumb_left');
		var thumbRegularRight = document.getElementById('Thumb_right');			
		thumbRegularLeft.setAttribute("transform", "translate(" + -100 + ", " + 0 + ")");
		thumbRegularRight.setAttribute("transform", "translate(" + 100 + ", " + 0 + ")");

		// hide ideal live corona
		var coronaLeft = document.getElementById('IdealLiveCoronaLeft');			
		var coronaRight = document.getElementById('IdealLiveCoronaRight');			
		coronaLeft.setAttribute("display","none");
		coronaRight.setAttribute("display","none");

		var step=0;
		setTimeout( 
			function() {
				coronaLeft.setAttribute("opacity",0.6);		// dim ideal live corona pressure outline element
				coronaRight.setAttribute("opacity",0.6);

				//Flash corona on and off when hand is in incorrect possition.
				window.timer = window.setInterval(	
					function() {
						if (step%2 == 0) {
							coronaLeft.setAttribute("display","inline");	// Display (on)
							coronaRight.setAttribute("display","inline");	// Display (on)
						}
						else {
							coronaLeft.setAttribute("display","none");		// Hide (off)
							coronaRight.setAttribute("display","none");		// Hide (off)
						}
						step++;
					}
					,500);		// Toggle ideal live corona outline on and off every 500 millisecond
			}
			, 500 );	

		// After ideal live corona flashes, start hand animation
		setTimeout(
			function() {
				var percentageMoved = 0;
				window.clearInterval(window.timer);

				coronaLeft.setAttribute("display","inline");		// Display ideal corona pressure outline element
				coronaRight.setAttribute("display","inline");

				window.timer = window.setInterval(
					function() {
						percentageMoved += 0.1;
						if (percentageMoved > 1) {
							window.clearInterval(window.timer); 
							setTimeout(
								function(){
									coronaLeft.setAttribute("opacity",1);			// Make bright
									coronaRight.setAttribute("opacity",1);
								}, 200); 
							setTimeout(function(){
								AnimatePeripheralitySpread();	//recursive call
							}, 2000); 
							return; 
						}
						else {
							var x = 100 * (1 - percentageMoved);

							// Apply the transformation 
							thumbRegularLeft.setAttribute("transform", "translate(" + -x + ", " + 0 + ")");
							thumbRegularRight.setAttribute("transform", "translate(" + x + ", " + 0 + ")");
						  	step++;
						}				
					} ,100);  
			}
			,2000);
	}

	/********************************************************************************
	 called by Update
	 Called when one of the peripherality arguments are set to true 
	 This function will display the peripherality animation.
	 Flow:
	   1. Deterine what peripherality is set.
	  		peripherality[] array set in html file
	   2. Call AnimatePeripherality or AnimatePeripheralitySpread to display peripherality animation forever
	   3. Animate with a loop forever in AnimatePeripherality or AnimatePeripheralitySpread

	INPUT: peripherality[] - contains up to three entries
	                       = left - 	left thumb is LSCAN_OBJECT_POSITION_TOO_LEFT
	                       = right - 	right thumb is LSCAN_OBJECT_POSITION_TOO_RIGHT
	                       = top - 		LSCAN_OBJECT_POSITION_TOO_HIGH
	 calculate position = 1 if left thumb is too far left
	                    = 2 if right thumb is too far right
	                    = 3 if left thumb is too left and too right => spread Hand
	                    = 4 if both thumbs are too high (top)
	                    = 5 if left thumb is too left and top
	                    = 6 if right thumb is too right and top
	                    = 7 if left, right and top => spread hand
	********************************************************************************/
	function SetPeripherality(peripherality) {
		// 1: left; 2: right; 3: spread Hand; 4: top; 5: left-top; 6: right-top
		var position = 0;
		if(peripherality.indexOf("left") != -1) position+= 1;	
		if(peripherality.indexOf("right") != -1) position+= 2;	
		if(peripherality.indexOf("top") != -1) position+= 4;

		switch(position) {
			case 1:
				// left thumb
				AnimatePeripherality(-100, 0)
				break;

			case 2:
				// right thumb 
				AnimatePeripherality(100, 0)
				break;

			case 3: case 7:
				// left + right = spread both thumbs
				AnimatePeripheralitySpread();
				break;

			case 4:
				// both thumbs LSCAN_OBJECT_POSITION_TOO_HIGH
				AnimatePeripherality(0, -60)
				break;

			case 5:
				// POSITION_TOO_LEFT and LSCAN_OBJECT_POSITION_TOO_HIGH
				AnimatePeripherality(-100, -60)
				break;

			case 6:
				// POSITION_TOO_RIGHT and LSCAN_OBJECT_POSITION_TOO_HIGH
				AnimatePeripherality(100, -60)
				break;

			case 7:
				// POSITION_TOO_LEFT and POSITION_TOO_RIGHT and POSITION_TOO_HIGH thus spread Hand
				AnimatePeripheralitySpread()
				break;

			default:
				break;
		}
	}

	/********************************************************************************
	 called from Update
	 Called when one of 2 pressure arguments are set
	 This function will display the good thumb placement image with live pressure corona.
	 This function does not do any animation.
	 Flow:
	   1. Get array of elements that contain the live pressure corona images
	       coronaArr has entry for each thumb
	   2. For each thumb
	          fill fingerCoronaTargetArr array with different pressure setting live pressure corona images
	   3. EvaluatePressureStage
	   4. if coronaArr entry matches pressure[] argument
	          display appropriate image
	   5. Set setFirstLooping flag to for web page reload and thus allow this animation
	   6. return

	INPUT: pressure[] - contains up to four entries
	                       = 0 - 	LSCAN_OBJECT_GOOD
	                       = 1 - 	LSCAN_OBJECT_TOO_LIGHT
	                       = -1 - 	LSCAN_OBJECT_TOO_DARK
	********************************************************************************/
	function SetPressure(pressure) {

		//Get live finger pressure corona for each position [0] left thumb [1] right thumb
		var coronaArr = ["PressureCoronaLeftThumb","PressureCoronaRightThumb"];

	  	var i;
		for (var i = 0; i < coronaArr.length; i++) {
			var fingerCoronaTarget = document.getElementById(coronaArr[i]);
		  	var fingerCoronaTargetArr = fingerCoronaTarget.getElementsByTagName('path');
	  		var s;
			for (s = 0; s < fingerCoronaTargetArr.length; s++) {
				if (s == EvaluatePressureStage(pressure[i]))
					fingerCoronaTargetArr[s].setAttribute("display","inline");	// display pressure corona
				else
					fingerCoronaTargetArr[s].setAttribute("display","none");	// hide non relevant pressure corons
			}				
		}

		window.parent.setFirstLooping(false);	// false will force web page to reload via svgobj.location.reload(true) call
	}

	/********************************************************************************
	called by SetPressure
	Called to determine which live pressure corona to display
	 ***** NOTE: *****
	    LSCAN_OBJECT_TOO_DARK live pressure corona element must be first in path!
	    Code does not use live pressure corona 2nd element in path!
	    LSCAN_OBJECT_GOOD live pressure corona element must be 3rd in path!
	    LSCAN_OBJECT_TOO_LIGHT live pressure corona element must be last (4th) in path!
	    Code does not use live pressure corona 5th element in path!
	INPUT: pressure - contains one pressure setting
	                       = 0 - 	LSCAN_OBJECT_GOOD
	                       = >0 - 	LSCAN_OBJECT_TOO_LIGHT
	                       = <0 - 	LSCAN_OBJECT_TOO_DARK
	********************************************************************************/
	function EvaluatePressureStage(pressure) {
		switch(pressure) {
			case 2:
				// LSCAN_OBJECT_TOO_DARK
				return 0;
				break;

			case 1:
				// LSCAN_OBJECT_TOO_DARK
				return 0;
				break;

			case 0:
				//LSCAN_OBJECT_GOOD
				return 2;
				break;

			case -1:
				//LSCAN_OBJECT_TOO_LIGHT
				return 3;
				break;

			case -2:
				//LSCAN_OBJECT_TOO_LIGHT
				return 3;
				break;

			default:
				break;
		}
		return null;
	}
